INSERT INTO routes (id, kind, name, region, status, difficulty, distance_km, gain_m, loss_m, date_start, date_end, from_point, to_point, season, forecast_link, bus_link, bdz_link, avtogari_link, route_line, verification_level, transport, huts, risk, days, accommodation, taxis, windy_embed, notes_default) VALUES ('P08', 'detailed', 'Синаница I', 'Пирин', 'Идея', 'Висока', 15, 1200, 1200, '', '', '', '', 'Юни – Октомври', '', '', '', '', 'Кресна → х. Синаница → х. Яне Сандански → Сандански', 'СРЕДНО — базовите данни са ясни, но липсва тук независима проверка на хижите и точните подходи.', '{"summary":"Подходящо за трансфер с кола до Кресна и изход с обществен транспорт от Сандански.","car":{"available":true,"text":"Кресна и Сандански са достъпни с кола; планинският участък започва от долината към х. Синаница.","parkingNote":"Паркирането в Кресна е по-лесно от горните пунктове; за край в Сандански има много паркинги и места за настаняване."},"public":{"steps":[{"from":"София","to":"Сандански","mode":"Автобус или влак","time":"около 2.5–4 ч","note":"След това местен транспорт/такси към Кресна."}]}}'::jsonb, '[{"name":"х. Синаница","elevation":null,"beds":null,"officialPhone":"0896 798 040","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Телефонът е наличен само от базовите данни и не е двукратно проверен."},{"name":"х. Яне Сандански","elevation":null,"beds":null,"officialPhone":"0896 766 174","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Липсват сигурни контактни и капацитетни данни в този вход."}]'::jsonb, '{"level":"ВИСОК","color":"rose","points":["Дълъг преход с голяма денивелация.","Планинският участък е подходящ само при стабилно време.","Крайната логистика е добра, но самият маршрут е натоварващ."],"conclusion":"Силен еднодневен или двудневен преход за подготвени туристи."}'::jsonb, '[{"date":null,"label":"Кресна → х. Синаница","type":"Преход","distance":"част от 24 км","gain":"част от +1200м","time":"5–7ч","stay":"х. Синаница","difficulty":"Висока"},{"date":null,"label":"х. Синаница → х. Яне Сандански → Сандански","type":"Преход","distance":"остатък от 24 км","gain":"остатък до +1200м / -1200м","time":"6–8ч","stay":"Сандански","difficulty":"Висока"}]'::jsonb, '[{"name":"Хотели в Сандански","location":"Сандански","rating":null,"price":null,"note":"Лесен финал с много опции."}]'::jsonb, '[{"name":"Местни таксита Сандански / Кресна","phone":null,"note":"Полезни за организиране на стартов трансфер към Кресна."}]'::jsonb, '', ''),
('P09', 'detailed', 'Синаница II', 'Пирин', 'Идея', 'Средна/Висока', 11, 1140, 1140, '', '', '', '', 'Юни – Октомври', '', '', '', '', 'Сандански → х. Синаница → Муратово езеро → х. Вихрен', 'СРЕДНО — базовите данни са налични, но маршрутът е логистично и теренно променлив според сезона.', '{"summary":"Добре комбинирано с обществен транспорт до Сандански и трансфер към долината.","car":{"available":true,"text":"Сандански и районът на долината са удобни за кола; горният участък към хижите е планински.","parkingNote":"Най-лесно е да се остави автомобилът в Сандански или на подходящо място по долния достъп."},"public":{"steps":[{"from":"София","to":"Сандански","mode":"Автобус или влак","time":"около 2.5–4 ч","note":"Следва трансфер до началото на пътеката."}]}}'::jsonb, '[{"name":"х. Синаница","elevation":null,"beds":null,"officialPhone":"0896 798 040","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Контактът идва от базовите данни; втори източник не е проверен тук."},{"name":"х. Вихрен","elevation":null,"beds":null,"officialPhone":"0889 890 442","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Телефонът е от базовите данни и е възможно да се промени сезонно."}]'::jsonb, '{"level":"ВИСОК","color":"rose","points":["Маршрутът е къс по километри, но с голяма денивелация.","Сезонно може да има остатъчен сняг и мокри камъни.","Прехвърлянето между две различни долини прави логистиката по-сложна."],"conclusion":"Технически и логистично по-сложен, отколкото изглежда по километри."}'::jsonb, '[{"date":null,"label":"Сандански → х. Синаница","type":"Преход","distance":"част от 11 км","gain":"част от +1140м","time":"4–6ч","stay":"х. Синаница","difficulty":"Средна/Висока"},{"date":null,"label":"х. Синаница → Муратово езеро → х. Вихрен","type":"Преход","distance":"остатък от 11 км","gain":"остатък до +1140м / -1140м","time":"5–7ч","stay":"х. Вихрен","difficulty":"Средна/Висока"}]'::jsonb, '[{"name":"Хотели в Сандански","location":"Сандански","rating":null,"price":null,"note":"Удобна база за старт."},{"name":"Хижарско настаняване","location":"х. Синаница / х. Вихрен","rating":null,"price":null,"note":"Най-практично за двудневен вариант."}]'::jsonb, '[{"name":"Местни таксита Сандански","phone":null,"note":"Полезни за трансфер към началото и за връщане от района на х. Вихрен."}]'::jsonb, '', ''),
('P10', 'detailed', 'Езерен кръг', 'Пирин', 'Идея', 'Средна', 22, 890, 700, '', '', '', '', 'Юни – Октомври', '', '', '', '', 'Банско → х. Демяница → Валявишки езера → х. Безбог', 'СРЕДНО — базовите данни са логични и последователни, но подробностите по хижите и транспортa не са двукратно проверени тук.', '{"summary":"Много подходящ за Банско като транспортна база; най-лесно е с кола до Банско и с местен трансфер към горната част.","car":{"available":true,"text":"Банско е удобна база с автомобил; до х. Безбог районът е планински и зависи от сезонния достъп.","parkingNote":"Паркирането в Банско е лесно, а при горните хижи е по-ограничено и сезонно."},"public":{"steps":[{"from":"София","to":"Банско","mode":"Автобус или влак + автобус","time":"около 3.5–5 ч","note":"След това местен трансфер към началото."}]}}'::jsonb, '[{"name":"х. Демяница","elevation":null,"beds":null,"officialPhone":"0877 79 94 06","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Няма потвърдени контактни данни в базовите входни данни."},{"name":"х. Безбог","elevation":null,"beds":null,"officialPhone":"+359 74 472120","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Телефонът е от базовите данни, но липсва второ независимо потвърждение тук."}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Маршрутът е дълъг, но не е екстремно техничен.","Езерният участък е чувствителен към мъгла и лоша видимост.","Подходящ е за добро време и ясно ориентиране."],"conclusion":"Баланс между красота и умерено натоварване, с добра логистика от Банско."}'::jsonb, '[{"date":null,"label":"Банско → х. Демяница","type":"Преход","distance":"част от 22 км","gain":"част от +890м","time":"4–6ч","stay":"х. Демяница","difficulty":"Средна"},{"date":null,"label":"х. Демяница → Валявишки езера → х. Безбог","type":"Преход","distance":"остатък от 22 км","gain":"остатък до +890м / -700м","time":"6–8ч","stay":"х. Безбог","difficulty":"Средна"}]'::jsonb, '[{"name":"Хотели и къщи за гости в Банско","location":"Банско","rating":null,"price":null,"note":"Най-удобна изходна база."}]'::jsonb, '[{"name":"Местни таксита Банско","phone":null,"note":"Полезни за достъп до долния старт и за връщане от района на х. Безбог."}]'::jsonb, '', '')
